// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// The Graph page's gestures: a click shows a node's details, a double-click loads its neighbours, literal values and
// types stay off the canvas until "Values" is pressed, and the legend selects the nodes of a type.
const REPOSITORY_ID = uniqueRepositoryId('graph-gestures');
const DATA = `
@prefix ex: <http://example.org/gestures/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
ex:alice a ex:Person ; rdfs:label "Alice" ; ex:age 39 ; ex:knows ex:bob .
ex:bob a ex:Person ; rdfs:label "Bob" ; ex:worksFor ex:acme .
ex:acme a ex:Organization ; rdfs:label "Acme" ; ex:location ex:oslo .
ex:oslo a ex:City ; rdfs:label "Oslo" .
`;

test.beforeAll(async ({ request }) => {
    const repositoryUrl = `${serverBaseUrl()}/repositories/${REPOSITORY_ID}`;
    const created = await request.put(repositoryUrl, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Graph gestures')
    });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${repositoryUrl}/statements`, {
        headers: { 'Content-Type': 'text/turtle' },
        data: DATA
    });
    expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

async function openGraphPage(page) {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    await explorer.getByRole('button', { name: 'Load 100 statements' }).click();
    await expect(explorer.locator('.graph-node', { hasText: 'Oslo' })).toBeAttached({ timeout: 30000 });
    return explorer;
}

function node(explorer, label) {
    return explorer.locator('.graph-node').filter({ has: explorer.page().locator('text', { hasText: label }) }).first();
}

test('the canvas draws the resources; a click shows a node\'s values and links', async ({ page }) => {
    const explorer = await openGraphPage(page);
    await expect(explorer.locator('.graph-node')).toHaveCount(4);
    await expect(explorer.locator('.graph-node.literal')).toHaveCount(0);
    await expect(explorer.locator('.graph-stats')).toHaveText('4 nodes · 3 links');

    await node(explorer, 'Alice').click();
    const details = explorer.locator('.node-details');
    await expect(details.locator('h3')).toHaveText('Alice');
    await expect(details.locator('.node-details-types')).toHaveText('Person');
    await expect(details.locator('.node-details-row', { hasText: 'age' })).toContainText('39');

    await details.getByRole('button', { name: 'Bob', exact: true }).click();
    await expect(details.locator('h3')).toHaveText('Bob');
    await details.getByRole('button', { name: 'Close details' }).click();
    await expect(details).toHaveCount(0);
});

test('Values draws literal values and types as nodes', async ({ page }) => {
    const explorer = await openGraphPage(page);
    const values = explorer.getByRole('button', { name: 'Show values and types as nodes' });
    await values.click();
    await expect(values).toHaveAttribute('aria-pressed', 'true');
    await expect(explorer.locator('.graph-node.literal').first()).toBeAttached();
    await expect(node(explorer, 'Person')).toBeAttached();
});

test('a double-click loads the neighbours of a node', async ({ page }) => {
    const explorer = await openGraphPage(page);
    await explorer.getByRole('button', { name: 'Query editor' }).click();
    await explorer.locator('#sparql').fill(
        'SELECT ?source ?predicate ?target WHERE { BIND(<http://example.org/gestures/alice> AS ?source) ?source ?predicate ?target }');
    await explorer.getByRole('button', { name: 'Run query' }).click();
    await expect(explorer.locator('.graph-node')).toHaveCount(2);
    await explorer.getByRole('button', { name: 'Close query workspace' }).click();

    await node(explorer, 'Bob').dblclick();
    await expect(node(explorer, 'Acme')).toBeAttached();
    await expect(explorer.locator('.status-text')).toHaveText('Added 1 linked node.');
});

test('the legend selects the nodes of a type', async ({ page }) => {
    const explorer = await openGraphPage(page);
    const person = explorer.locator('.legend button', { hasText: 'Person' });
    await person.click();
    await expect(person).toHaveAttribute('aria-pressed', 'true');
    await expect(explorer.locator('.selection-summary strong')).toHaveText('2 nodes match the filters');
    await expect(explorer.locator('.graph-node.is-selected')).toHaveCount(2);
    await person.click();
    await expect(explorer.locator('.selection-summary')).toHaveCount(0);
});
